TOVSHCHYNA = {"halochka": 5}

STRILKA = ['<path d="M4 12h39"/>', '<path d="M36 5l7 7-7 7"/>']


def lin(w):
    return f'fill="none" stroke="currentColor" stroke-width="{w}" stroke-linecap="round" stroke-linejoin="round"'


def sprite():
    out = ['<svg xmlns="http://www.w3.org/2000/svg" style="display:none">',
           '<!-- Іконки МРТ ПЛЮС. Сітка 48×48, колір – currentColor.',
           '     Health Icons (healthicons.org), MIT, © Resolve to Save Lives; решта – власні.',
           '     Джерело – docs/ikony.py, перезбирати: python3 docs/ikony.py assets/img/ikony-mrt.svg -->']
    for k, v in HEALTHICONS.items():
        out.append(f'<symbol id="ik-{k}" viewBox="0 0 48 48">{v["svg"]}</symbol>')
    for k, els in VLASNI.items():
        out.append(f'<symbol id="ik-{k}" viewBox="0 0 48 48" {lin(TOVSHCHYNA.get(k, 2))}>' + ''.join(els) + '</symbol>')
    out.append(f'<symbol id="ik-strilka" viewBox="0 0 48 24" {lin(2)}>' + ''.join(STRILKA) + '</symbol>')
    out.append('</svg>')
    return '\n'.join(out) + '\n'


